-- Fournitex — base ADV (fictif, épreuve recrutement youmanIT)
SET NAMES utf8mb4;

DROP TABLE IF EXISTS clients;
CREATE TABLE clients (client_id VARCHAR(10),raison_sociale VARCHAR(120),contact_nom VARCHAR(80),contact_email VARCHAR(150),conditions_paiement VARCHAR(20),remise_contractuelle_pct VARCHAR(5),segment VARCHAR(20),actif VARCHAR(2)) DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS factures;
CREATE TABLE factures (facture_id VARCHAR(15),client_id VARCHAR(10),date_emission VARCHAR(12),date_echeance VARCHAR(12),montant_ht VARCHAR(12),tva_pct VARCHAR(5),montant_ttc VARCHAR(12),statut VARCHAR(12)) DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS paiements;
CREATE TABLE paiements (paiement_id VARCHAR(10),facture_id VARCHAR(15),date_paiement VARCHAR(12),montant VARCHAR(12),mode VARCHAR(12)) DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS catalogue;
CREATE TABLE catalogue (reference VARCHAR(15),libelle VARCHAR(120),famille VARCHAR(20),prix_unitaire_ht VARCHAR(10),tva_pct VARCHAR(5)) DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS demandes_devis;
CREATE TABLE demandes_devis (demande_id VARCHAR(10),date_reception VARCHAR(12),client_id VARCHAR(10),email_expediteur VARCHAR(150),message TEXT,langue VARCHAR(5)) DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS modeles_courriers;
CREATE TABLE modeles_courriers (code_modele VARCHAR(30),declencheur VARCHAR(60),objet_modele VARCHAR(255),corps_modele TEXT) DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS litiges;
CREATE TABLE litiges (facture_id VARCHAR(15),date_ouverture VARCHAR(12),motif VARCHAR(200),statut VARCHAR(10)) DEFAULT CHARSET=utf8mb4;
